export class Engine{constructor(s){Object.assign(this,s);this.lastTime=0;this.running=false;this.ui.mount();this.dayNight.attach(this.time);this.quests.start()}start(){if(this.running)return;this.running=true;requestAnimationFrame(this.loop.bind(this))}loop(t){if(!this.running)return;const dt=Math.min((t-this.lastTime)/1000||0,.05);this.lastTime=t;this.update(dt);this.render();requestAnimationFrame(this.loop.bind(this))}update(dt){this.input.update(dt);this.time.update(dt);this.dayNight.update(dt);this.world.update(dt);this.navigation.update(dt);this.schedule.update();this.traffic.update(dt);this.entities.update(dt);this.quests.update();this.ui.update();this.camera.follow(this.entities.getPlayer())}render(){this.renderer.begin();this.world.draw(this.renderer.ctx,this.camera);this.entities.draw(this.renderer.ctx,this.camera);this.dayNight.draw(this.renderer.ctx);this.ui.draw();this.renderer.end()}}
